function setupMoneyCalculations(){const rent=document.querySelector('#detail-money [name="rent"]'),rentUnit=document.querySelector('#detail-money [name="rentUnitPrice"]'),size=document.querySelector('#detail-lease [name="size"]');if(!rent||!rentUnit||!size)return;rentUnit.readOnly=true;rentUnit.title='월세 ÷ 전용면적(평)으로 자동 계산';const update=()=>{const monthly=Number(rent.value),sqm=Number(size.value);rentUnit.value=monthly>0&&sqm>0?(monthly/(sqm/SQM_PER_PYEONG)).toFixed(2):'';};rent.addEventListener('input',update);size.addEventListener('input',update);update();}
