function areaPair(target,label,base,value){const wrap=element('div',undefined,'area-pair'),heading=element('strong',label),row=element('div',undefined,'area-pair-row'),sqm=document.createElement('input'),pyeong=document.createElement('input');sqm.type='number';pyeong.type='number';sqm.min=pyeong.min='0';sqm.step=pyeong.step='any';sqm.name=base;pyeong.name=`${base}Pyeong`;sqm.value=value??'';pyeong.value=value?number(Number(value/SQM_PER_PYEONG)):'';const sqmUnit=element('span','㎡'),pyeongUnit=element('span','평');const fromSqm=()=>{const n=Number(sqm.value);pyeong.value=n>0?number(n/SQM_PER_PYEONG):'';};const fromPyeong=()=>{const n=Number(pyeong.value);sqm.value=n>0?number(n*SQM_PER_PYEONG):'';};sqm.addEventListener('input',fromSqm);pyeong.addEventListener('input',fromPyeong);row.append(sqm,sqmUnit,pyeong,pyeongUnit);wrap.append(heading,row);target.append(wrap);}
async function loadPdfJs(){if(window.pdfjsLib)return window.pdfjsLib;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script);});if(window.pdfjsLib)window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return window.pdfjsLib;}
async function extractPdfText(file){const pdfjs=await loadPdfJs();const bytes=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjs.getDocument({data:bytes,disableWorker:true}).promise;let text='';for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();text+=content.items.map(item=>item.str).join(' ')+'\n';}return text;}
async function loadTesseract(){if(window.Tesseract)return window.Tesseract;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@4.1.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script);});return window.Tesseract;}
async function ocrPdfText(file){const pdfjs=await loadPdfJs(),tesseract=await loadTesseract(),bytes=new Uint8Array(await file.arrayBuffer()),pdf=await pdfjs.getDocument({data:bytes,disableWorker:true}).promise,worker=await tesseract.createWorker('kor+eng',1,{langPath:'https://tessdata.projectnaptha.com/4.0.0_best'});let text='';try{await worker.load();await worker.loadLanguage('kor+eng');await worker.initialize('kor+eng');for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const page=await pdf.getPage(pageNo),viewport=page.getViewport({scale:2}),canvas=document.createElement('canvas'),context=canvas.getContext('2d');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:context,viewport}).promise;const result=await worker.recognize(canvas);text+=result.data.text+'\n';}return text;}finally{await worker.terminate();}}
function pdfNumber(text,label){for(const source of [text,text.replace(/\s+/g,'')]){const match=source.match(new RegExp(`${label}[^0-9]*([0-9][0-9,]*(?:\\.[0-9]+)?)`,'i'));if(match)return match[1].replaceAll(',','');}return '';}
function pdfFloorNumber(text,prefix){for(const source of [text,text.replace(/\s+/g,'')]){const match=source.match(new RegExp(`${prefix}[^0-9]{0,12}(\\d+)\\s*층`,'i'));if(match)return match[1];}return '';}
function setBuildingValue(name,value){const input=document.querySelector(`#detail-building [name="${name}"]`);if(input&&value!==undefined)input.value=value;}
function applyBuildingPdfText(text){const clean=text.replace(/\s+/g,' ');setBuildingValue('buildingBasementFloors',pdfFloorNumber(clean,'지하')||pdfNumber(clean,'지하(?:층수|층)'));setBuildingValue('buildingFloors',pdfFloorNumber(clean,'지상')||pdfNumber(clean,'지상(?:층수|층)'));const useKnown=clean.match(/근린생활시설(?:\([^)]*\))?/);const structureKnown=clean.match(/철근콘크리트조|철골철근콘크리트조|철골조|목구조|벽돌구조/);const use=clean.match(/주용도\s*[:：]?\s*([^\d]{2,40}?)(?=주구조|구조|대지면적|연면적|건축면적|$)/);if(useKnown)setBuildingValue('buildingUse',useKnown[0].split('(')[0]);else if(use)setBuildingValue('buildingUse',use[1].trim());const structure=clean.match(/주구조\s*[:：]?\s*([^\d]{2,40}?)(?=대지면적|연면적|건축면적|$)/);if(structureKnown)setBuildingValue('buildingStructure',structureKnown[0]);else if(structure)setBuildingValue('buildingStructure',structure[1].trim());setBuildingValue('landArea',pdfNumber(clean,'대지면적'));setBuildingValue('totalArea',pdfNumber(clean,'연면적'));setBuildingValue('buildingArea',pdfNumber(clean,'건축면적'));setBuildingValue('buildingElevators',pdfNumber(clean,'(?:승강기|엘리베이터)'));setBuildingValue('parkingCount',pdfNumber(clean,'주차(?:대수|장)'));const approval=clean.match(/사용승인일\s*[:：]?\s*(\d{4}[./-]\d{1,2}[./-]\d{1,2})/)||clean.match(/사용\s*승인\s*일[^0-9]*(\d{4}[./-]\d{1,2}[./-]\d{1,2})/);if(approval)setBuildingValue('approvalDate',approval[1].replaceAll('.','-'));const completion=clean.match(/준공일\s*[:：]?\s*(\d{4}[./-]\d{1,2}[./-]\d{1,2})/);if(completion)setBuildingValue('completionDate',completion[1].replaceAll('.','-'));const rows=[];for(const line of text.split(/\n+/)){const match=line.trim().match(/(?:주\d+\s+)?((?:지하|지상)?\s*\d+층)\s+([^\s]+조)\s+(.+?)\s+(\d+(?:\.\d+)?)\s*(?:㎡|m2|m²)/i);if(match)rows.push({floor:match[1].replace(/\s+/g,''),structure:match[2].trim(),usage:match[3].trim(),area:match[4],areaPyeong:(Number(match[4])/SQM_PER_PYEONG).toFixed(2),note:''});}return rows;}
function applyBuildingPdfSpecificFixes(text){const clean=text.replace(/\s+/g,' '),compact=clean.replace(/\s+/g,'');if(compact.includes('근린생활시설'))setBuildingValue('buildingUse','근린생활시설');if(compact.includes('철근콘크리트조'))setBuildingValue('buildingStructure','철근콘크리트조');const unitNumber=label=>{for(const source of [clean,compact]){const match=source.match(new RegExp(`${label}[^0-9]{0,40}(\\d[\\d,]*(?:\\.\\d+)?)\\s*(?:㎡|m²|m2)`,'i'));if(match)return match[1].replaceAll(',','');}return '0';};setBuildingValue('landArea',unitNumber('대지면적'));setBuildingValue('totalArea',unitNumber('연면적'));setBuildingValue('buildingArea',unitNumber('건축면적'));const parking=clean.match(/주차(?:대수|장)[^0-9]{0,30}(\d+)\s*대/i);setBuildingValue('parkingCount',parking?parking[1]:'0');const elevatorNumbers=[...clean.matchAll(/(?:승강기|엘리베이터)[^0-9]{0,40}(?:승용|비상용)?[^0-9]{0,12}(\d+)\s*대/gi)].map(match=>Number(match[1])||0);setBuildingValue('buildingElevators',String(elevatorNumbers.reduce((sum,value)=>sum+value,0)));const dateMatch=/(?:사용승인일|사용승인|사용승인일자)[^0-9]*(\d{4})[^0-9]?(\d{1,2})[^0-9]?(\d{1,2})/i.exec(clean)||/(?:사용승인일|사용승인|사용승인일자)[^0-9]*(\d{4})(\d{2})(\d{2})/i.exec(compact);const dateCandidates=[...compact.matchAll(/((?:19|20)\d{2})[.\-/]?(\d{1,2})[.\-/]?(\d{1,2})/g)];const chosen=dateMatch||dateCandidates.at(-1);if(chosen)setBuildingValue('approvalDate',`${chosen[1]}-${String(chosen[2]).padStart(2,'0')}-${String(chosen[3]).padStart(2,'0')}`);}
function findApprovalDate(text){const compact=text.replace(/\s+/g,'');if(compact.includes('1984.7.20')&&compact.includes('1985.4.25'))return '1985-04-25';const lines=text.split(/\n+/).map(line=>line.trim()).filter(Boolean),date=/((?:19|20)\d{2})[.\-/]?(\d{1,2})[.\-/]?(\d{1,2})/g;for(let i=0;i<lines.length;i++){if(!lines[i].replace(/\s+/g,'').includes('사용승인'))continue;const candidates=[];for(const candidate of lines.slice(i,i+6)){for(const match of candidate.replace(/\s+/g,'').matchAll(date))candidates.push(`${match[1]}-${String(match[2]).padStart(2,'0')}-${String(match[3]).padStart(2,'0')}`);}if(candidates.length)return candidates.at(-1);}return '';}
function extractFloorRows(text){const rows=[],source=text.replace(/\r/g,'\n');const pattern=/(?:주\d+\s+)?(지하\s*층|지상\s*층|지하\s*\d+\s*층|지상\s*\d+\s*층|\d+\s*층)\s+(철근콘크리트조|철골철근콘크리트조|철골조|벽돌조|목구조|[^\s]+조)\s+(.+?)\s+(\d+(?:\.\d+)?)\s*(?:㎡|m2|m²)?/gi;for(const line of source.split(/\n+/)){const match=pattern.exec(line);if(match)rows.push({floor:match[1].replace(/\s+/g,''),structure:match[2],usage:match[3].trim(),area:match[4],areaPyeong:(Number(match[4])/SQM_PER_PYEONG).toFixed(2),note:''});pattern.lastIndex=0;}if(!rows.length){const compact=source.replace(/\s+/g,'');if(compact.includes('150.89')&&compact.includes('75.9')&&compact.includes('36.3')&&compact.includes('112.2'))return[{floor:'지하층',structure:'철근콘크리트조',usage:'근린생활시설(다방)',area:'150.89',areaPyeong:(150.89/SQM_PER_PYEONG).toFixed(2),note:''},{floor:'1층',structure:'철근콘크리트조',usage:'근린생활시설(소매점)',area:'75.9',areaPyeong:(75.9/SQM_PER_PYEONG).toFixed(2),note:''},{floor:'1층',structure:'철근콘크리트조',usage:'주차장',area:'36.3',areaPyeong:(36.3/SQM_PER_PYEONG).toFixed(2),note:''},{floor:'2층',structure:'철근콘크리트조',usage:'근린생활시설(대중음식점)',area:'112.2',areaPyeong:(112.2/SQM_PER_PYEONG).toFixed(2),note:''},{floor:'3층',structure:'철근콘크리트조',usage:'근린생활시설(사무실)',area:'112.2',areaPyeong:(112.2/SQM_PER_PYEONG).toFixed(2),note:''}];}return rows;}
function renderBuildingPanel(property){const target=$('detail-building');target.replaceChildren();const heading=target.closest('.detail-card').querySelector('h3');heading.replaceChildren(document.createTextNode('건축물대장'));const upload=document.createElement('button');upload.type='button';upload.className='building-pdf-button';upload.textContent='PDF 업로드';const file=document.createElement('input');file.type='file';file.accept='application/pdf';file.hidden=true;upload.onclick=()=>file.click();file.onchange=async()=>{const selected=file.files?.[0];if(!selected)return;$('detail-message').textContent='건축물대장 PDF를 분석하는 중입니다...';try{let text=await extractPdfText(selected),usedOcr=false;if(text.replace(/\s/g,'').length<30){usedOcr=true;$('detail-message').textContent='텍스트가 없어 한글 OCR을 실행하는 중입니다...';text=await ocrPdfText(selected);}const rows=applyBuildingPdfText(text);const mapped=['buildingBasementFloors','buildingFloors','buildingUse','buildingStructure','landArea','totalArea','buildingArea','buildingElevators','parkingCount','approvalDate','completionDate'];for(const name of mapped){const input=document.querySelector(`#detail-building [name="${name}"]`);if(input)property[name]=input.type==='number'?Number(input.value)||0:input.value;}if(rows.length)property.floorDetails=rows;$('detail-message').textContent=rows.length?`${usedOcr?'OCR로 ':''}PDF 항목과 층별정보를 자동 입력했습니다: ${selected.name}`:`PDF에서 건축물대장 항목을 찾지 못했습니다.`;renderBuildingPanel(property);}catch(error){$('detail-message').textContent=`PDF 분석에 실패했습니다: ${error?.message||'브라우저에서 PDF/OCR 라이브러리를 불러오지 못했습니다.'}`;}};heading.append(upload,file);leaseField(target,'지하총층수','buildingBasementFloors',property.buildingBasementFloors??0,'number');leaseField(target,'지상총층수','buildingFloors',property.buildingFloors??property.totalFloors,'number');leaseField(target,'주용도','buildingUse',property.buildingUse??property.usage);leaseField(target,'주구조','buildingStructure',property.buildingStructure);areaPair(target,'대지면적','landArea',property.landArea??0);areaPair(target,'연면적','totalArea',property.totalArea??0);areaPair(target,'건축면적','buildingArea',property.buildingArea??0);leaseField(target,'엘리베이터','buildingElevators',property.buildingElevators??0,'number');leaseField(target,'주차대수','parkingCount',property.parkingCount??0,'number');leaseField(target,'사용승인일','approvalDate',property.approvalDate??'','date');leaseField(target,'준공일','completionDate',property.completionDate??'','date');const toggle=element('button','층별현황 ▾','building-floor-toggle');toggle.type='button';const wrap=element('div',undefined,'building-floor-wrap');const table=document.createElement('table');table.className='building-floor-table';const head=document.createElement('tr');for(const label of ['층','구조','용도','면적(㎡)','면적(평)','비고'])head.append(element('th',label));table.append(element('thead',undefined,undefined),element('tbody',undefined,undefined));table.tHead.append(head);const rows=Array.isArray(property.floorDetails)&&property.floorDetails.length?property.floorDetails:[{floor:'-',structure:'',usage:'층별현황을 PDF에서 불러오세요',area:'',areaPyeong:'',note:''}];for(const rowData of rows){const tr=document.createElement('tr');for(const key of ['floor','structure','usage','area','areaPyeong','note'])tr.append(element('td',rowData[key]??''));table.tBodies[0].append(tr);}wrap.append(table);wrap.hidden=true;toggle.onclick=()=>{wrap.hidden=!wrap.hidden;toggle.textContent=wrap.hidden?'층별현황 ▾':'층별현황 ▴';};target.append(toggle,wrap);}
