function setupAddressSearch(){const input=document.querySelector('#detail-location [name="address"]');if(!input)return;const dd=input.closest('dd');dd.classList.add('address-field');const button=element('button','⌕','text-button');button.type='button';button.title='네이버지도에서 주소 검색';button.setAttribute('aria-label','네이버지도에서 주소 검색');button.classList.add('location-search-button');button.onclick=()=>{const address=input.value.trim();if(!address){$('detail-message').textContent='주소를 먼저 입력해 주세요.';input.focus();return;}window.open(`https://map.naver.com/p/search/${encodeURIComponent(address)}`,'_blank','noopener');$('detail-message').textContent='입력한 주소를 네이버지도 검색으로 연결했습니다.';};dd.append(button);}
