function updateDetailManager(property){const actions=document.querySelector('.detail-head-actions');if(!actions)return;if(!document.getElementById('detail-manager-style')){const style=element('style');style.id='detail-manager-style';style.textContent='.detail-head-actions{display:flex;flex-direction:column;align-items:flex-end;gap:7px;margin-top:-10px}.detail-modal-head{padding-bottom:8px!important;margin-bottom:8px!important}.detail-manager-meta{display:flex;align-items:center;gap:6px;font-size:11px;color:#7a8aa2}.detail-manager-meta input{width:120px;padding:5px 7px;border:1px solid #b9c9df;border-radius:4px;background:#fff;color:#214a87;font-size:11px}.detail-head-buttons{display:flex;gap:8px;align-items:center}.detail-head-buttons #detail-save{margin:0;padding:7px 11px;font-size:11px}.detail-head-buttons #detail-close{padding:7px 11px;background:#e67e22;border:1px solid #e67e22;border-radius:4px;color:#fff}.detail-footer{display:none!important}';document.head.append(style);}let meta=$('detail-manager-meta');if(!meta){meta=element('div',undefined,'detail-manager-meta');meta.id='detail-manager-meta';const label=element('span','담당자');const value=document.createElement('input');value.id='detail-manager';value.name='manager';value.type='text';value.placeholder='담당자 입력';meta.append(label,value);actions.insertBefore(meta,actions.firstChild);}meta.querySelector('input').value=property.manager||'';let buttons=actions.querySelector('.detail-head-buttons');if(!buttons){buttons=element('div',undefined,'detail-head-buttons');const edit=$('detail-edit'),close=$('detail-close');if(edit)buttons.append(edit);if(close)buttons.append(close);actions.append(buttons);}const save=$('detail-save');if(save&&save.parentElement!==buttons)buttons.insertBefore(save,buttons.firstChild);}
function briefEscape(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function openBriefingPreview(property){const address=property.address||property.area||'';const floor=property.floor?property.floor<0?`지하 ${Math.abs(property.floor)}층`:`${property.floor}층`:'미입력';const total=property.buildingFloors??property.totalFloors??'';const money=(label,value)=>`<div class="money"><span>${label}</span><b>${briefEscape(value||'미입력')}</b></div>`;const rows=(Array.isArray(property.floorDetails)?property.floorDetails:[]).map(row=>`<tr><td>${briefEscape(row.floor)}</td><td>${briefEscape(row.structure)}</td><td>${briefEscape(row.usage)}</td><td>${briefEscape(row.area)}</td><td>${briefEscape(row.areaPyeong)}</td></tr>`).join('')||'<tr><td colspan="5">층별현황이 없습니다.</td></tr>';const win=window.open('','_blank','width=1250,height=900');if(!win){$('detail-message').textContent='브리핑 창을 열 수 없습니다. 브라우저의 팝업 차단을 해제해 주세요.';return;}win.document.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>고객 브리핑 · ${briefEscape(property.name)}</title><style>*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#20344f;font-family:"Malgun Gothic","Noto Sans KR",Arial,sans-serif}.toolbar{position:fixed;right:20px;top:16px;z-index:5}.toolbar button{border:1px solid #2d67b5;background:#2d67b5;color:#fff;padding:9px 13px;border-radius:5px;cursor:pointer}.sheet{max-width:1100px;margin:20px auto;background:#fff;box-shadow:0 10px 30px #20344f18}.page{min-height:760px;padding:34px 42px;position:relative;page-break-after:always}.page:last-child{page-break-after:auto}.page h1{font-size:25px;color:#173b68;margin:0 0 6px}.page h2{font-size:17px;color:#173b68;border-bottom:2px solid #173b68;padding-bottom:8px;margin:0 0 17px}.sub{font-size:11px;color:#7789a1;margin-bottom:16px}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;align-items:start}.photo{aspect-ratio:16/9;border-radius:8px;background:linear-gradient(135deg,#d5e0ec,#7894b5 55%,#274568);display:flex;align-items:flex-end;padding:16px;color:#fff}.photo strong{font-size:23px;line-height:1.4}.facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-content:start;align-items:start}.fact,.money{border:1px solid #dbe4ef;border-radius:6px;padding:10px}.fact:first-child,.fact:nth-child(2){grid-column:1/-1}.fact span,.money span{display:block;color:#71839b;font-size:10px}.fact b,.money b{display:block;color:#244c82;font-size:13px;margin-top:4px;line-height:1.4}.title{font-size:12px;color:#173b68;font-weight:700;border-bottom:1px solid #aabed6;padding-bottom:6px;margin:18px 0 8px}.money-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.table{width:100%;border-collapse:collapse;font-size:11px}.table th,.table td{border-bottom:1px solid #e5ebf2;padding:8px;text-align:left}.table th{background:#f7f9fc;color:#72849d;font-weight:500}.maps{display:grid;grid-template-columns:1fr 1fr;gap:14px}.map{height:500px;border:1px solid #cbd8e8;border-radius:8px;background:repeating-linear-gradient(35deg,#f2f6fa 0 16px,#e8eef5 16px 18px);position:relative}.map.cadastral{background:linear-gradient(90deg,#fbf5de 0 23%,transparent 23% 25%,#f6e4d5 25% 49%,transparent 49% 51%,#e2f0dc 51% 76%,transparent 76%),repeating-linear-gradient(22deg,#fff9e9 0 21px,#e7d8ba 21px 22px)}.map strong{display:block;background:#ffffffeb;padding:11px;font-size:12px}.map a{position:absolute;right:10px;top:8px;background:#fff;border:1px solid #a9bfdc;border-radius:4px;padding:6px;color:#295d9c;text-decoration:none;font-size:10px}.map p{position:absolute;left:15px;right:15px;bottom:15px;background:#ffffffdf;padding:10px;border-radius:5px;color:#71839b;font-size:10px}.building{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.building .fact{min-height:66px}.watermark{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-28deg);font-size:34px;letter-spacing:3px;color:#244c82;opacity:.10;white-space:nowrap;pointer-events:none;font-weight:700}.footer{position:absolute;left:42px;right:42px;bottom:18px;border-top:1px solid #dbe4ef;padding-top:7px;text-align:center;color:#9a5e5e;font-size:9px}@media(max-width:760px){.sheet{margin:0}.page{padding:24px 18px;min-height:0}.grid,.maps{grid-template-columns:1fr}.money-grid,.building{grid-template-columns:1fr 1fr}.map{height:340px}}@media print{body{background:#fff}.toolbar{display:none}.sheet{box-shadow:none;margin:0}.page{min-height:277mm;height:277mm}}</style></head><body><div class="toolbar"><button onclick="window.print()">브리핑 인쇄 / PDF 저장</button></div><main class="sheet"><section class="page"><div class="watermark">대톡스부동산 · 무단복사 및 배포 금지</div><h1>${briefEscape(property.name||'매물 브리핑')}</h1><div class="sub">매물번호 ${briefEscape(property.code)} · 담당자 ${briefEscape(property.manager||'미지정')}</div><div class="grid"><div class="photo"></div><div class="facts"><div class="fact title-fact"><span>매물명</span><b>${briefEscape(property.name||"미입력")}</b></div><div class="fact"><span>위치정보</span><b>${briefEscape(address)}</b></div><div class="fact"><span>임대층 / 총층</span><b>${briefEscape(floor)} / ${briefEscape(total||'미입력')}층</b></div><div class="fact"><span>전용면적</span><b>${briefEscape(property.size?`${property.size}㎡ (${(property.size/SQM_PER_PYEONG).toFixed(2)}평)`:'미입력')}</b></div></div></div><div class="title">금액정보</div><div class="money-grid">${money('보증금',`${property.deposit??0}만원`)}${money('월세',`${property.rent??0}만원`)}${money('관리비',`${property.maintenance??0}만원`)}${money('권리금',property.premium||'무권리')}</div><div class="title">임대정보</div><table class="table"><tr><th>추천용도</th><td>${briefEscape(property.usage||'미입력')}</td><th>분류</th><td>${briefEscape(property.category||'미입력')}</td></tr><tr><th>냉난방</th><td>${briefEscape(property.heating||'미입력')}</td><th>엘리베이터</th><td>${briefEscape(property.elevator||'미입력')}</td></tr><tr><th>주차</th><td>${briefEscape(property.parkingCount??0)}대</td><th>층고</th><td>${briefEscape(property.ceilingHeight||'미입력')}</td></tr></table><div class="footer">무단복사 및 배포 시 법적 처벌을 받을 수 있습니다.</div></section><section class="page"><div class="watermark">대톡스부동산 · 무단복사 및 배포 금지</div><h2>02. 위치 및 토지 현황</h2><div class="sub">주소: ${briefEscape(address)}</div><div class="maps"><div class="map"><strong>카카오맵 · 대상 위치</strong><a href="https://map.kakao.com/?q=${encodeURIComponent(address)}" target="_blank">카카오맵 열기</a><p>추후 카카오맵 API 연결 후 주소 기반 지도와 주변 시설을 표시합니다.</p></div><div class="map cadastral"><strong>지적편집도 · 필지 및 도로 관계</strong><a href="https://map.kakao.com/?q=${encodeURIComponent(address)}" target="_blank">지도에서 확인</a><p>추후 지적편집도 레이어와 용도지역·도로 접면 정보를 표시합니다.</p></div></div><div class="footer">무단복사 및 배포 시 법적 처벌을 받을 수 있습니다.</div></section><section class="page"><div class="watermark">대톡스부동산 · 무단복사 및 배포 금지</div><h2>03. 건축물대장 요약</h2><div class="building"><div class="fact"><span>주용도</span><b>${briefEscape(property.buildingUse||'미입력')}</b></div><div class="fact"><span>주구조</span><b>${briefEscape(property.buildingStructure||'미입력')}</b></div><div class="fact"><span>지상 총층수</span><b>${briefEscape(property.buildingFloors??property.totalFloors??0)}층</b></div><div class="fact"><span>사용승인일</span><b>${briefEscape(property.approvalDate||'미입력')}</b></div><div class="fact"><span>대지면적</span><b>${briefEscape(property.landArea??0)}㎡</b></div><div class="fact"><span>연면적</span><b>${briefEscape(property.totalArea??0)}㎡</b></div><div class="fact"><span>건축면적</span><b>${briefEscape(property.buildingArea??0)}㎡</b></div><div class="fact"><span>주차 / 승강기</span><b>${briefEscape(property.parkingCount??0)}대 / ${briefEscape(property.buildingElevators??0)}대</b></div></div><div class="title">층별현황</div><table class="table"><thead><tr><th>층</th><th>구조</th><th>용도</th><th>면적(㎡)</th><th>면적(평)</th></tr></thead><tbody>${rows}</tbody></table><div class="footer">무단복사 및 배포 시 법적 처벌을 받을 수 있습니다.</div></section></main></body></html>`);win.document.close();win.focus();}
function setupBriefingButton(property){const buttons=document.querySelector('.detail-head-buttons');if(!buttons)return;let button=$('detail-briefing');if(!button){button=element('button','브리핑','detail-briefing');button.type='button';buttons.insertBefore(button,buttons.lastElementChild||null);}button.onclick=()=>openBriefingPreview(property);}
function renderPropertyDetailForm(property){
 updateDetailManager(property);setupBriefingButton(property);
 for(const id of ['detail-basic','detail-location','detail-money','detail-lease','detail-building'])$(id).replaceChildren();
 detailInput($('detail-basic'),'자체관리','selfManage',property.selfManage);detailInput($('detail-basic'),'추천용도','usage',property.usage);detailInput($('detail-basic'),'매물명','name',property.name);detailInput($('detail-basic'),'분류','category',property.category,'text',categoryOptions);detailInput($('detail-basic'),'진행상태','status',property.status,'text',['준비','진행','상황','보류','거래완료']);detailInput($('detail-basic'),'기타','otherCategory',property.otherCategory);detailInput($('detail-basic'),'고객명','customerName',property.customerName);detailInput($('detail-basic'),'전화번호','customerPhone',property.customerPhone);const managerHidden=document.createElement('input');managerHidden.type='hidden';managerHidden.name='manager';managerHidden.value=property.manager??'';$('detail-basic').append(managerHidden);const basicFields=$('detail-basic').children;for(const index of [4,5,10,11]){basicFields[index].classList.add('basic-wide');}
 for(const [name,value] of [['area',property.area],['floor',property.floor],['totalFloors',property.totalFloors],['source',property.source]]){const hidden=document.createElement('input');hidden.type='hidden';hidden.name=name;hidden.value=value??'';$('detail-location').append(hidden);}const mainPhoto=ensureMainPhotoBox();mainPhoto.replaceChildren(element('span','메인 사진'));setupPhotoUploadButton();detailInput($('detail-location'),'주소','address',property.address);setupAddressSearch();
 $('detail-money').replaceChildren();moneyInput($('detail-money'),'보증금','deposit',property.deposit);moneyInput($('detail-money'),'월세','rent',property.rent);moneyInput($('detail-money'),'월세평단가','rentUnitPrice',property.rentUnitPrice);moneyInput($('detail-money'),'관리비','maintenance',property.maintenance);moneyInput($('detail-money'),'권리금','premium',property.premium,'text');moneyInput($('detail-money'),'입금가','entryPrice',property.entryPrice,'text');moneyInput($('detail-money'),'관리비부연설명','maintenanceNote',property.maintenanceNote,'text');
 $('detail-lease').replaceChildren();const floorRow=element('div',undefined,'lease-floor-row');leaseField(floorRow,'층수','floorTypeStart','지상','text',['지상','지하']);leaseField(floorRow,'','floorStart',property.floor<0?Math.abs(property.floor):property.floor,'number');floorRow.append(element('span','층 ~','floor-separator'));leaseField(floorRow,'','floorTypeEnd','지상','text',['지상','지하']);leaseField(floorRow,'','floorEnd',property.totalFloors,'number');floorRow.append(element('span','층','floor-unit'));$('detail-lease').append(floorRow);areaPair($('detail-lease'),'임대면적','leaseSize',property.leaseSize);areaPair($('detail-lease'),'전용면적','size',property.size);const options=['개별','중앙'];leaseField($('detail-lease'),'냉난방','heating',property.heating,'text',options);leaseField($('detail-lease'),'가스','gas',property.gas,'text',['도시','LPG']);leaseField($('detail-lease'),'화장실','toilet',property.toilet);leaseField($('detail-lease'),'엘리베이터','elevator',property.elevator,'text',['O','X']);leaseField($('detail-lease'),'층고','ceilingHeight',property.ceilingHeight);leaseField($('detail-lease'),'위반건축물','illegalBuilding',property.illegalBuilding,'text',['O','X']);setupMoneyCalculations();
 renderBuildingPanel(property);
 $('detail-save').hidden=false;$('detail-save').textContent='저장하고 닫기';$('detail-edit').hidden=true;$('detail-close').textContent='취소';$('detail-message').textContent='모든 입력칸을 바로 수정할 수 있습니다. 저장하고 닫기를 누르면 반영됩니다.';
}
function renderPropertyDetailView(property){
 updateDetailManager(property);detailRows($('detail-basic'),[['매물번호',property.code],['분류',property.category],['진행 상태',property.status],['추천 용도',property.usage]]);detailRows($('detail-location'),[['지역',property.area],['주소',property.address],['임대층',property.floor<0?`지하 ${Math.abs(property.floor)}층`:`${property.floor}층`],['건물 총층',`${property.totalFloors}층`],['정보 출처',property.source]]);detailRows($('detail-money'),[['보증금',`${number(property.deposit)} 만원`],['월세',`${number(property.rent)} 만원`],['권리금',`${number(property.premium)} 만원`],['관리비',`${number(property.maintenance)} 만원`],['상태','금액은 가상 정보']]);detailRows($('detail-lease'),[['전용면적',`${number(property.size)}㎡ (${number(property.size/SQM_PER_PYEONG)}평)`],['용도',property.usage],['광고 상태',property.status],['최종 확인일',property.updated],['메모',property.memo]]);detailRows($('detail-building'),[['건물명',property.buildingName],['주용도',property.buildingUse],['지상 총층수',`${property.totalFloors}층`],['구조',property.buildingStructure],['건축물대장',property.buildingRegister]]);$('detail-save').hidden=true;$('detail-edit').textContent='내용 수정';
}
function openPropertyDetail(property){
 detailIsNew=false;detailPropertyId=property.id;$('detail-title').textContent=property.name;$('detail-subtitle').textContent=`매물번호 ${property.code} · ${property.status} · ${property.updated}`;renderPropertyDetailForm(property);
 detailDraftWorklogs=data.worklogs.filter(item=>item.propertyId===property.id).map(item=>({...item}));detailPhotoDraft=Array.isArray(property.photos)?property.photos.map(item=>({...item})):[];worklogPage=1;renderWorklogPanel(property);$('detail-description').value=property.memo||'';$('detail-message').textContent='';renderPhotoPreview(detailPhotoDraft);$('property-detail').showModal();
}
function openNewPropertyDetail(){const nextCode=String(Math.max(1000,...data.properties.map(item=>Number(item.code)||0))+1),draft={id:`draft-${Date.now()}`,code:nextCode,name:'새 매물',area:'',address:'',floor:1,totalFloors:1,size:0,deposit:0,rent:0,premium:0,maintenance:0,category:'상가',status:'준비',usage:'',favorite:false,selfManage:'',otherCategory:'',customerName:'',customerPhone:'',manager:'',updated:today(),memo:'',buildingName:'',buildingUse:'',buildingStructure:'',buildingRegister:'추후 연결',source:'가상 입력',photos:[]};data={...data,properties:[...data.properties,draft]};detailIsNew=true;detailPropertyId=draft.id;detailPhotoDraft=[];$('detail-title').textContent='새 매물 등록';$('detail-subtitle').textContent=`임시 매물번호 ${draft.code} · 저장 전 입력`;renderPropertyDetailForm(draft);detailDraftWorklogs=[];worklogPage=1;renderWorklogPanel(draft);$('detail-description').value='';$('detail-message').textContent='새 매물 정보를 입력한 뒤 저장하고 닫기를 눌러 주세요.';renderPhotoPreview(detailPhotoDraft);$('property-detail').showModal();}
function renderPhotoPreview(files){const preview=$('detail-photo-preview');preview.replaceChildren();const main=ensureMainPhotoBox();main.replaceChildren();const items=Array.isArray(files)?files:[];if(!items.length){main.append(element('span','메인 사진'));return;}const first=items[0];const firstUrl=first.dataUrl||URL.createObjectURL(first);const mainImage=document.createElement('img');mainImage.src=firstUrl;mainImage.alt=`메인 사진 · ${first.name||'사진'}`;main.append(mainImage,element('span',first.name||'메인 사진','main-photo-caption'));for(const item of items){const figure=element('figure'),image=document.createElement('img');image.src=item.dataUrl||URL.createObjectURL(item);image.alt=item.name||'사진';const caption=element('figcaption',item.name||'사진');figure.append(image,caption);preview.append(figure);}}
function readPhotoFiles(files){return Promise.all([...files].map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,dataUrl:String(reader.result)});reader.onerror=reject;reader.readAsDataURL(file);})));}
function renderLinkedCustomers(property){const linked=data.interactions.filter(item=>item.propertyId===property.id),box=$('detail-customers');box.replaceChildren();if(!linked.length){box.append(element('p','연결된 고객이 없습니다. 상담·후속 업무에서 고객을 연결해 주세요.','subtle'));return;}for(const item of linked){const customer=data.customers.find(c=>c.id===item.customerId),card=element('div',undefined,'detail-customer');if(!customer){card.append(element('span','삭제된 고객','subtle'));box.append(card);continue;}const fields=[['고객 별칭','name','text'],['희망 업종','purpose','text'],['희망 지역','area','text'],['월세 예산','budget','number'],['고객 상태','status','text']];card.append(element('strong',`${customer.name} · 연결 고객`));for(const [label,key,type] of fields){const wrap=element('label',label),input=element('input');input.type=type;input.name=`customer-${customer.id}-${key}`;input.value=customer[key]??'';if(type==='number'){input.min='0';input.step='any';}wrap.append(input);card.append(wrap);}const note=element('textarea');note.name=`customer-${customer.id}-memo`;note.value=customer.memo??'';note.placeholder='고객 메모';card.append(note);box.append(card);}}
function ensureWorklogStyles(){if(document.getElementById('worklog-style'))return;const style=element('style');style.id='worklog-style';style.textContent='.worklog-panel{display:flex;flex-direction:column;gap:8px}.worklog-compose{display:grid;grid-template-columns:92px 1fr auto;gap:6px}.worklog-compose textarea{grid-column:1/-1;min-height:48px;resize:vertical;padding:7px;border:1px solid #b9c9df;border-radius:4px;font:inherit;font-size:11px}.worklog-compose input,.worklog-compose select{padding:7px;border:1px solid #b9c9df;border-radius:4px;background:white;font-size:11px}.worklog-compose button{grid-column:3;justify-self:end;align-self:stretch;min-width:64px;padding:5px 8px;background:#0d3279;color:white;border:0;border-radius:4px;font-size:10px}.worklog-compose button:hover,.worklog-compose button:focus{background:#0d3279;color:white}.worklog-history{height:150px;min-height:150px;max-height:150px;overflow:auto;border-top:1px solid #e5ebf3;padding-top:6px}.worklog-entry{border-bottom:1px solid #e5ebf3;padding:7px 0}.worklog-entry strong{display:block;color:#284d88;font-size:10px}.worklog-entry p{font-size:11px;margin-top:4px;white-space:pre-wrap}.worklog-entry small{color:#8b98aa;font-size:9px}.worklog-pager{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#7c8ca5}.worklog-pager button{padding:4px 8px;font-size:10px}.worklog-empty{padding:28px 4px;text-align:center;color:#8998ac;font-size:11px}@media(max-width:850px){.worklog-compose{grid-template-columns:1fr 1fr auto}.worklog-compose textarea{grid-column:1/-1}.worklog-compose button{grid-column:3}}';document.head.append(style);}
